use std::collections::BTreeSet;

pub fn qualified_ref(kind: &str, name: &str) -> Option<String> {
    if name.is_empty() || name.starts_with('/') || name.chars().any(|c| c.is_ascii_whitespace() || c == ':') {
        return None;
    }
    let section = match kind { "branch" => "heads", "tag" => "tags", _ => return None };
    Some(format!("refs/{section}/{name}:refs/{section}/{name}"))
}

pub fn project_slug(remote: &str) -> Option<String> {
    let clean = remote.trim_matches(char::is_ascii_whitespace).trim_end_matches('/');
    let leaf = clean.rsplit(['/', ':']).next()?;
    let slug = leaf.strip_suffix(".git").unwrap_or(leaf);
    (!slug.is_empty()).then(|| slug.to_string())
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RepoPlan {
    pub primary: String,
    pub supporting: Vec<String>,
    pub tags: Vec<String>,
}

impl RepoPlan {
    pub fn tracked_refs(&self) -> Vec<String> {
        let mut seen = BTreeSet::new();
        let mut out = Vec::new();
        for (kind, name) in std::iter::once(("branch", &self.primary))
            .chain(self.supporting.iter().map(|n| ("branch", n)))
            .chain(self.tags.iter().map(|n| ("tag", n)))
        {
            if let Some(reference) = qualified_ref(kind, name) {
                if seen.insert(reference.clone()) { out.push(reference); }
            }
        }
        out
    }
}
